	            sh: this._isShared,
	            ch: this._cacheHeuristic,
	            imm: this._immutableMinTtl,
	            icc: this._ignoreCargoCult,
	            st: this._status,
	            resh: this._resHeaders,
	            rescc: this._rescc,
	            m: this._method,
	            u: this._url,
	            h: this._host,
	            a: this._noAuthorization,
	            reqh: this._reqHeaders,
	            reqcc: this._reqcc,
